class Trie{static class N{N[]c=new N[26];boolean end;}N r=new N();public Trie(){}public void insert(String w){N p=r;for(char x:w.toCharArray()){int k=x-'a';if(p.c[k]==null)p.c[k]=new N();p=p.c[k];}p.end=true;}public boolean search(String w){N p=r;for(char x:w.toCharArray()){p=p.c[x-'a'];if(p==null)return false;}return p.end;}public boolean startsWith(String w){N p=r;for(char x:w.toCharArray()){p=p.c[x-'a'];if(p==null)return false;}return true;}}
